// Erwartet aufgaben als kommagetrennte Papierkram-Aufgaben-IDs, z. B. "781,784"
const ids = [...new Set(String($('Start durch Workflow').first().json.aufgaben || '').split(',').map(x => x.trim()).filter(Boolean))];
if (!ids.length) throw new Error('Keine Aufgaben-IDs übergeben.');
if (ids.some(id => !/^\d+$/.test(id))) throw new Error('Ungültige Aufgaben-ID übergeben.');
return ids.map(task_id => ({ json: { task_id } }));

// Je Aufgabe die Dienstleistung (null = keine eigene, dann gilt die des Projekts). Fehlt eine Aufgabe, Abbruch.
const soll = $('Aufgaben aufteilen').all().map(i => String(i.json.task_id));
const aufgaben = {};
for (const i of $input.all()) {
  const t = i.json || {};
  if (t.type !== 'task') continue;
  const p = t.proposition;
  aufgaben[String(t.id)] = p ? { id: String(p.id), name: String(p.name || ''), preis: Number(p.price), einheit: String(p.time_unit || '') } : null;
}
const fehlt = soll.filter(id => !(id in aufgaben));
if (fehlt.length) throw new Error('Aufgabe(n) ' + fehlt.join(', ') + ' in Papierkram nicht abrufbar.');
return [{ json: { aufgaben } }];
